# [doc = " A queue of delayed elements."] # [doc = ""] # [doc = " Once an element is inserted into the `DelayQueue`, it is yielded once the"] # [doc = " specified deadline has been reached."] # [doc = ""] # [doc = " # Usage"] # [doc = ""] # [doc = " Elements are inserted into `DelayQueue` using the [`insert`] or"] # [doc = " [`insert_at`] methods. A deadline is provided with the item and a [`Key`] is"] # [doc = " returned. The key is used to remove the entry or to change the deadline at"] # [doc = " which it should be yielded back."] # [doc = ""] # [doc = " Once delays have been configured, the `DelayQueue` is used via its"] # [doc = " [`Stream`] implementation. [`poll_expired`] is called. If an entry has reached its"] # [doc = " deadline, it is returned. If not, `Poll::Pending` is returned indicating that the"] # [doc = " current task will be notified once the deadline has been reached."] # [doc = ""] # [doc = " # `Stream` implementation"] # [doc = ""] # [doc = " Items are retrieved from the queue via [`DelayQueue::poll_expired`]. If no delays have"] # [doc = " expired, no items are returned. In this case, [`Poll::Pending`] is returned and the"] # [doc = " current task is registered to be notified once the next item's delay has"] # [doc = " expired."] # [doc = ""] # [doc = " If no items are in the queue, i.e. `is_empty()` returns `true`, then `poll`"] # [doc = " returns `Poll::Ready(None)`. This indicates that the stream has reached an end."] # [doc = " However, if a new item is inserted *after*, `poll` will once again start"] # [doc = " returning items or `Poll::Pending`."] # [doc = ""] # [doc = " Items are returned ordered by their expirations. Items that are configured"] # [doc = " to expire first will be returned first. There are no ordering guarantees"] # [doc = " for items configured to expire at the same instant. Also note that delays are"] # [doc = " rounded to the closest millisecond."] # [doc = ""] # [doc = " # Implementation"] # [doc = ""] # [doc = " The [`DelayQueue`] is backed by a separate instance of a timer wheel similar to that used internally"] # [doc = " by Tokio's standalone timer utilities such as [`sleep`]. Because of this, it offers the same"] # [doc = " performance and scalability benefits."] # [doc = ""] # [doc = " State associated with each entry is stored in a [`slab`]. This amortizes the cost of allocation,"] # [doc = " and allows reuse of the memory allocated for expired entries."] # [doc = ""] # [doc = " Capacity can be checked using [`capacity`] and allocated preemptively by using"] # [doc = " the [`reserve`] method."] # [doc = ""] # [doc = " # Cancellation safety"] # [doc = ""] # [doc = " [`DelayQueue`]'s implementation of [`StreamExt::next`] is cancellation safe."] # [doc = ""] # [doc = " # Usage"] # [doc = ""] # [doc = " Using [`DelayQueue`] to manage cache entries."] # [doc = ""] # [doc = " ```rust,no_run"] # [doc = " use tokio_util::time::{DelayQueue, delay_queue};"] # [doc = ""] # [doc = " use std::collections::HashMap;"] # [doc = " use std::task::{ready, Context, Poll};"] # [doc = " use std::time::Duration;"] # [doc = " # type CacheKey = String;"] # [doc = " # type Value = String;"] # [doc = ""] # [doc = " struct Cache {"] # [doc = "     entries: HashMap<CacheKey, (Value, delay_queue::Key)>,"] # [doc = "     expirations: DelayQueue<CacheKey>,"] # [doc = " }"] # [doc = ""] # [doc = " const TTL_SECS: u64 = 30;"] # [doc = ""] # [doc = " impl Cache {"] # [doc = "     fn insert(&mut self, key: CacheKey, value: Value) {"] # [doc = "         let delay = self.expirations"] # [doc = "             .insert(key.clone(), Duration::from_secs(TTL_SECS));"] # [doc = ""] # [doc = "         self.entries.insert(key, (value, delay));"] # [doc = "     }"] # [doc = ""] # [doc = "     fn get(&self, key: &CacheKey) -> Option<&Value> {"] # [doc = "         self.entries.get(key)"] # [doc = "             .map(|&(ref v, _)| v)"] # [doc = "     }"] # [doc = ""] # [doc = "     fn remove(&mut self, key: &CacheKey) {"] # [doc = "         if let Some((_, cache_key)) = self.entries.remove(key) {"] # [doc = "             self.expirations.remove(&cache_key);"] # [doc = "         }"] # [doc = "     }"] # [doc = ""] # [doc = "     fn poll_purge(&mut self, cx: &mut Context<'_>) -> Poll<()> {"] # [doc = "         while let Some(entry) = ready!(self.expirations.poll_expired(cx)) {"] # [doc = "             self.entries.remove(entry.get_ref());"] # [doc = "         }"] # [doc = ""] # [doc = "         Poll::Ready(())"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " [`insert`]: method@Self::insert"] # [doc = " [`insert_at`]: method@Self::insert_at"] # [doc = " [`Key`]: struct@Key"] # [doc = " [`Stream`]: https://docs.rs/futures/0.3.31/futures/stream/trait.Stream.html"] # [doc = " [`StreamExt::next`]: https://docs.rs/tokio-stream/0.1.17/tokio_stream/trait.StreamExt.html#method.next"] # [doc = " [`poll_expired`]: method@Self::poll_expired"] # [doc = " [`Stream::poll_expired`]: method@Self::poll_expired"] # [doc = " [`DelayQueue`]: struct@DelayQueue"] # [doc = " [`sleep`]: fn@tokio::time::sleep"] # [doc = " [`slab`]: slab"] # [doc = " [`capacity`]: method@Self::capacity"] # [doc = " [`reserve`]: method@Self::reserve"] # [derive (Debug)] pub struct DelayQueue < T > { # [doc = " Stores data associated with entries"] slab : SlabStorage < T > , # [doc = " Lookup structure tracking all delays in the queue"] wheel : Wheel < Stack < T > > , # [doc = " Delays that were inserted when already expired. These cannot be stored"] # [doc = " in the wheel"] expired : Stack < T > , # [doc = " Delay expiring when the *first* item in the queue expires"] delay : Option < Pin < Box < Sleep > > > , # [doc = " Wheel polling state"] wheel_now : u64 , # [doc = " Instant at which the timer starts"] start : Instant , # [doc = " Waker that is invoked when we potentially need to reset the timer."] # [doc = " Because we lazily create the timer when the first entry is created, we"] # [doc = " need to awaken any poller that polled us before that point."] waker : Option < Waker > , }
