impl < T > wheel :: Stack for Stack < T > { type Owned = Key ; type Borrowed = Key ; type Store = SlabStorage < T > ; fn is_empty (& self) -> bool { self . head . is_none () } fn push (& mut self , item : Self :: Owned , store : & mut Self :: Store) { debug_assert ! (store [item] . next . is_none ()) ; debug_assert ! (store [item] . prev . is_none ()) ; let old = self . head . take () ; if let Some (idx) = old { store [idx] . prev = Some (item) ; } store [item] . next = old ; self . head = Some (item) ; } fn pop (& mut self , store : & mut Self :: Store) -> Option < Self :: Owned > { if let Some (key) = self . head { self . head = store [key] . next ; if let Some (idx) = self . head { store [idx] . prev = None ; } store [key] . next = None ; debug_assert ! (store [key] . prev . is_none ()) ; Some (key) } else { None } } fn peek (& self) -> Option < Self :: Owned > { self . head } # [track_caller] fn remove (& mut self , item : & Self :: Borrowed , store : & mut Self :: Store) { let key = * item ; assert ! (store . contains (item)) ; debug_assert ! ({ let mut next = self . head ; let mut contains = false ; while let Some (idx) = next { let data = & store [idx] ; if idx == * item { debug_assert ! (! contains) ; contains = true ; } next = data . next ; } contains }) ; if let Some (next) = store [key] . next { store [next] . prev = store [key] . prev ; } if let Some (prev) = store [key] . prev { store [prev] . next = store [key] . next ; } else { self . head = store [key] . next ; } store [key] . next = None ; store [key] . prev = None ; } fn when (item : & Self :: Borrowed , store : & Self :: Store) -> u64 { store [* item] . when } }
