cfg_rt ! { # [doc = " A set of tasks which are executed on the same thread."] # [doc = ""] # [doc = " In some cases, it is necessary to run one or more futures that do not"] # [doc = " implement [`Send`] and thus are unsafe to send between threads. In these"] # [doc = " cases, a [local task set] may be used to schedule one or more `!Send`"] # [doc = " futures to run together on the same thread."] # [doc = ""] # [doc = " For example, the following code will not compile:"] # [doc = ""] # [doc = " ```rust,compile_fail"] # [doc = " use std::rc::Rc;"] # [doc = ""] # [doc = " #[tokio::main]"] # [doc = " async fn main() {"] # [doc = "     // `Rc` does not implement `Send`, and thus may not be sent between"] # [doc = "     // threads safely."] # [doc = "     let nonsend_data = Rc::new(\"my nonsend data...\");"] # [doc = ""] # [doc = "     let nonsend_data = nonsend_data.clone();"] # [doc = "     // Because the `async` block here moves `nonsend_data`, the future is `!Send`."] # [doc = "     // Since `tokio::spawn` requires the spawned future to implement `Send`, this"] # [doc = "     // will not compile."] # [doc = "     tokio::spawn(async move {"] # [doc = "         println!(\"{}\", nonsend_data);"] # [doc = "         // ..."] # [doc = "     }).await.unwrap();"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " # Use with `run_until`"] # [doc = ""] # [doc = " To spawn `!Send` futures, we can use a local task set to schedule them"] # [doc = " on the thread calling [`Runtime::block_on`]. When running inside of the"] # [doc = " local task set, we can use [`task::spawn_local`], which can spawn"] # [doc = " `!Send` futures. For example:"] # [doc = ""] # [doc = " ```rust"] # [doc = " use std::rc::Rc;"] # [doc = " use tokio::task;"] # [doc = ""] # [doc = " # #[tokio::main(flavor = \"current_thread\")]"] # [doc = " # async fn main() {"] # [doc = " let nonsend_data = Rc::new(\"my nonsend data...\");"] # [doc = ""] # [doc = " // Construct a local task set that can run `!Send` futures."] # [doc = " let local = task::LocalSet::new();"] # [doc = ""] # [doc = " // Run the local task set."] # [doc = " local.run_until(async move {"] # [doc = "     let nonsend_data = nonsend_data.clone();"] # [doc = "     // `spawn_local` ensures that the future is spawned on the local"] # [doc = "     // task set."] # [doc = "     task::spawn_local(async move {"] # [doc = "         println!(\"{}\", nonsend_data);"] # [doc = "         // ..."] # [doc = "     }).await.unwrap();"] # [doc = " }).await;"] # [doc = " # }"] # [doc = " ```"] # [doc = " **Note:** The `run_until` method can only be used in `#[tokio::main]`,"] # [doc = " `#[tokio::test]` or directly inside a call to [`Runtime::block_on`]. It"] # [doc = " cannot be used inside a task spawned with `tokio::spawn`."] # [doc = ""] # [doc = " ## Awaiting a `LocalSet`"] # [doc = ""] # [doc = " Additionally, a `LocalSet` itself implements `Future`, completing when"] # [doc = " *all* tasks spawned on the `LocalSet` complete. This can be used to run"] # [doc = " several futures on a `LocalSet` and drive the whole set until they"] # [doc = " complete. For example,"] # [doc = ""] # [doc = " ```rust"] # [doc = " use tokio::{task, time};"] # [doc = " use std::rc::Rc;"] # [doc = ""] # [doc = " # #[tokio::main(flavor = \"current_thread\")]"] # [doc = " # async fn main() {"] # [doc = " let nonsend_data = Rc::new(\"world\");"] # [doc = " let local = task::LocalSet::new();"] # [doc = ""] # [doc = " let nonsend_data2 = nonsend_data.clone();"] # [doc = " local.spawn_local(async move {"] # [doc = "     // ..."] # [doc = "     println!(\"hello {}\", nonsend_data2)"] # [doc = " });"] # [doc = ""] # [doc = " local.spawn_local(async move {"] # [doc = "     time::sleep(time::Duration::from_millis(100)).await;"] # [doc = "     println!(\"goodbye {}\", nonsend_data)"] # [doc = " });"] # [doc = ""] # [doc = " // ..."] # [doc = ""] # [doc = " local.await;"] # [doc = " # }"] # [doc = " ```"] # [doc = " **Note:** Awaiting a `LocalSet` can only be done inside"] # [doc = " `#[tokio::main]`, `#[tokio::test]` or directly inside a call to"] # [doc = " [`Runtime::block_on`]. It cannot be used inside a task spawned with"] # [doc = " `tokio::spawn`."] # [doc = ""] # [doc = " ## Use inside `tokio::spawn`"] # [doc = ""] # [doc = " The two methods mentioned above cannot be used inside `tokio::spawn`, so"] # [doc = " to spawn `!Send` futures from inside `tokio::spawn`, we need to do"] # [doc = " something else. The solution is to create the `LocalSet` somewhere else,"] # [doc = " and communicate with it using an [`mpsc`] channel."] # [doc = ""] # [doc = " The following example puts the `LocalSet` inside a new thread."] # [doc = " ```"] # [doc = " # #[cfg(not(target_family = \"wasm\"))]"] # [doc = " # {"] # [doc = " use tokio::runtime::Builder;"] # [doc = " use tokio::sync::{mpsc, oneshot};"] # [doc = " use tokio::task::LocalSet;"] # [doc = ""] # [doc = " // This struct describes the task you want to spawn. Here we include"] # [doc = " // some simple examples. The oneshot channel allows sending a response"] # [doc = " // to the spawner."] # [doc = " #[derive(Debug)]"] # [doc = " enum Task {"] # [doc = "     PrintNumber(u32),"] # [doc = "     AddOne(u32, oneshot::Sender<u32>),"] # [doc = " }"] # [doc = ""] # [doc = " #[derive(Clone)]"] # [doc = " struct LocalSpawner {"] # [doc = "    send: mpsc::UnboundedSender<Task>,"] # [doc = " }"] # [doc = ""] # [doc = " impl LocalSpawner {"] # [doc = "     pub fn new() -> Self {"] # [doc = "         let (send, mut recv) = mpsc::unbounded_channel();"] # [doc = ""] # [doc = "         let rt = Builder::new_current_thread()"] # [doc = "             .enable_all()"] # [doc = "             .build()"] # [doc = "             .unwrap();"] # [doc = ""] # [doc = "         std::thread::spawn(move || {"] # [doc = "             let local = LocalSet::new();"] # [doc = ""] # [doc = "             local.spawn_local(async move {"] # [doc = "                 while let Some(new_task) = recv.recv().await {"] # [doc = "                     tokio::task::spawn_local(run_task(new_task));"] # [doc = "                 }"] # [doc = "                 // If the while loop returns, then all the LocalSpawner"] # [doc = "                 // objects have been dropped."] # [doc = "             });"] # [doc = ""] # [doc = "             // This will return once all senders are dropped and all"] # [doc = "             // spawned tasks have returned."] # [doc = "             rt.block_on(local);"] # [doc = "         });"] # [doc = ""] # [doc = "         Self {"] # [doc = "             send,"] # [doc = "         }"] # [doc = "     }"] # [doc = ""] # [doc = "     pub fn spawn(&self, task: Task) {"] # [doc = "         self.send.send(task).expect(\"Thread with LocalSet has shut down.\");"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // This task may do !Send stuff. We use printing a number as an example,"] # [doc = " // but it could be anything."] # [doc = " //"] # [doc = " // The Task struct is an enum to support spawning many different kinds"] # [doc = " // of operations."] # [doc = " async fn run_task(task: Task) {"] # [doc = "     match task {"] # [doc = "         Task::PrintNumber(n) => {"] # [doc = "             println!(\"{}\", n);"] # [doc = "         },"] # [doc = "         Task::AddOne(n, response) => {"] # [doc = "             // We ignore failures to send the response."] # [doc = "             let _ = response.send(n + 1);"] # [doc = "         },"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " #[tokio::main]"] # [doc = " async fn main() {"] # [doc = "     let spawner = LocalSpawner::new();"] # [doc = ""] # [doc = "     let (send, response) = oneshot::channel();"] # [doc = "     spawner.spawn(Task::AddOne(10, send));"] # [doc = "     let eleven = response.await.unwrap();"] # [doc = "     assert_eq!(eleven, 11);"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " [`Send`]: trait@std::marker::Send"] # [doc = " [local task set]: struct@LocalSet"] # [doc = " [`Runtime::block_on`]: method@crate::runtime::Runtime::block_on"] # [doc = " [`task::spawn_local`]: fn@spawn_local"] # [doc = " [`mpsc`]: mod@crate::sync::mpsc"] pub struct LocalSet { # [doc = " Current scheduler tick."] tick : Cell < u8 >, # [doc = " State available from thread-local."] context : Rc < Context >, # [doc = " This type should not be Send."] _not_send : PhantomData <* const () >, } }
